import { after } from 'next/server';

export async function POST(
  request: Request,
  { params }: { params: Promise<{ id: string }> },
) {
  const { id } = await params;
  const { partialMessage } = await request.json();

  // Persist the partial response
  await updateChat(id, {
    messages: [...messages, partialMessage],
    activeStreamId: null,
  });

  // Cancel the stream work (implementation depends on your stream setup)
  await cancelStreamWork(chat.activeStreamId);

  // Ensure work continues after response
  after(async () => {
    // Additional cleanup if needed
  });

  return new Response(null, { status: 204 });
